-- =============================================================================
-- 1970 Form and status catalogue rationalisation, first slice (Business Architecture Rebase phase 11; CDF-198, CDF-199)
-- Requirements: §12, §14, §18, §45, §68; playbook §7–§16, §115; owner Q&A Q13–Q19, Q21, Q30, Q41, Q57, Q71–Q82, Q94;
-- ADR-028, ADR-029, ADR-035; owner register DEC-31 (narrowed), DEC-34 (status model), DEC-35 (open)
--
-- Reference data only. Schema `config`:
--   target_class            the 15 target classes a legacy form can become, with what each asks for and produces.
--   target_module           61 platform modules: domain object, api.* commands, permissions, UI surface, delivery
--                           state and the migrations that delivered it. The traceability spine (playbook §115).
--   legacy_catalogue        the six legacy sources: two status catalogues (150 Drive, 140 owner catalogue D), the
--                           live CDF_CASE_V1 workflow states, and three form sources (169 CRM, 19 WB-FRM, 274 D).
--   status_dimension        the multi-dimensional status model (DEC-34): where each dimension is held (a check-
--                           constrained column, config.status_code, a derivation, or not yet modelled).
--   status_dimension_value  every value of every dimension. Stored values equal the column's check constraint or
--                           config.status_code exactly; derived and planned values say how they will be computed.
--   legacy_status_map       305 legacy statuses keyed by (catalogue, code): each maps to a dimension value, an audit
--                           event and/or a domain object, and a module. Ten codes (S021–S023, S025–S028, S030, S099,
--                           S100) mean different things in the two status catalogues; both readings are kept and
--                           marked code_conflict.
--   legacy_form_map         462 legacy forms keyed by (catalogue, sequence): target class, module, merge target,
--                           disposition, owner and actor; catalogue D rows also carry their status codes.
--   + six reason codes named by catalogue D (config.status_code, OWNER_DEFAULT).
--
-- Controls:
--   * Additive: nothing is deleted, disabled or renamed. Every WB-FRM form stays enabled; its retirement from new-case
--     use is SOURCE_REQUIRED (a decision record, §88). No option code changes (DEC-35 stays open).
--   * Read-only for application roles: RLS enabled, SELECT for signed-in users, no write grants. The rows hold catalogue
--     labels and codes only: no case data, no personal data.
--   * Planned and derived values are marked PLANNED; gaps found while mapping are referenced as P11-G1..G6 and listed
--     in FORM_CATALOGUE_RATIONALIZATION.md §6.
-- =============================================================================

create table config.target_class (
  code             text primary key check (code ~ '^[A-Z][A-Z_]{2,39}$'),
  description      text not null,
  required_data    text not null,
  generated_output text not null
);
comment on table config.target_class is
  'What a legacy form becomes (playbook §11–§15; ADR-028). Only USER_FORM items are forms people fill in.';

create table config.target_module (
  code           text primary key check (code ~ '^[A-Z][A-Z0-9_]{2,59}$'),
  name_en        text not null,
  domain_object  text not null,
  commands       text[] not null default '{}',
  permissions    text[] not null default '{}',
  ui_surface     text not null check (ui_surface in ('PORTAL', 'EMPLOYEE_PORTAL', 'MY_WORK', 'INTAKE', 'CASES',
                                                     'MY_COMMITTEES', 'RECORDS', 'OVERSIGHT', 'ADMINISTRATION',
                                                     'REPORTING')),
  delivery_state text not null check (delivery_state in ('IMPLEMENTED', 'PARTIAL', 'PLANNED', 'SOURCE_REQUIRED')),
  delivered_in   text[] not null default '{}',
  notes          text not null,
  check ((delivery_state in ('IMPLEMENTED', 'PARTIAL')) = (cardinality(delivered_in) > 0))
);
comment on table config.target_module is
  'Where legacy forms and statuses land (playbook §115): domain object, commands, permissions, UI surface (ADR-030).';
comment on column config.target_module.delivered_in is 'Four-digit migration numbers that built the module.';

create table config.legacy_catalogue (
  code       text primary key check (code ~ '^[A-Z][A-Z0-9_]{2,59}$'),
  kind       text not null check (kind in ('STATUS', 'WORKFLOW_STATE', 'FORM')),
  name_en    text not null,
  source     text not null,
  item_count int not null check (item_count > 0)
);
comment on table config.legacy_catalogue is 'The legacy sources that Phase 11 rationalises; item_count equals the mapped rows.';

create table config.status_dimension (
  code            text primary key check (code ~ '^[A-Z][A-Z0-9_]{2,59}$'),
  name_en         text not null,
  semantic_type   text not null check (semantic_type in ('PRIMARY_STAGE', 'SUBSTATUS', 'WAIT_REASON', 'SUSPENSION_REASON',
                                                         'OUTCOME', 'FLAG', 'LEGAL_STATE', 'EXECUTION_STATE',
                                                         'RECORDS_STATE')),
  kind            text not null check (kind in ('STORED', 'STATUS_CODE', 'DERIVED', 'PLANNED')),
  held_on         text not null,
  source_relation text,
  source_column   text,
  notes           text,
  check ((kind in ('STORED', 'STATUS_CODE')) = (source_relation is not null and source_column is not null))
);
comment on table config.status_dimension is
  'The multi-dimensional status model (DEC-34, ADR-029): no single case-status enum; display status is derived.';

create table config.status_dimension_value (
  dimension     text not null references config.status_dimension (code),
  value         text not null check (value ~ '^[A-Z][A-Z0-9_]{1,59}$'),
  state         text not null check (state in ('ACTIVE', 'PLANNED')),
  derivation    text,
  source_status text not null check (source_status in ('OWNER_DEFAULT', 'SOURCE_REQUIRED', 'APPROVED')),
  primary key (dimension, value)
);
comment on table config.status_dimension_value is
  'Every value of every status dimension. ACTIVE values are stored today; PLANNED values are derived or not built yet.';

create table config.legacy_status_map (
  catalogue          text not null references config.legacy_catalogue (code),
  legacy_code        text not null check (legacy_code ~ '^[A-Z][A-Z0-9_]{1,39}$'),
  legacy_name_ar     text not null,
  legacy_name_en     text,
  semantic_type      text not null check (semantic_type in ('PRIMARY_STAGE', 'SUBSTATUS', 'WAIT_REASON',
                                                            'SUSPENSION_REASON', 'OUTCOME', 'FLAG', 'EVENT',
                                                            'LEGAL_STATE', 'EXECUTION_STATE', 'RECORDS_STATE',
                                                            'DERIVED_DISPLAY_STATUS', 'OBSOLETE', 'DUPLICATE')),
  target_dimension   text,
  target_value       text,
  target_context     text,
  target_event       text check (target_event ~ '^[A-Z][A-Z0-9_]{2,59}$'),
  target_event_state text check (target_event_state in ('IMPLEMENTED', 'PLANNED')),
  target_object      text,
  target_module      text not null references config.target_module (code),
  disposition        text not null check (disposition in ('KEEP', 'MERGE', 'REPLACE', 'DUPLICATE', 'RETIRE')),
  duplicate_of       text,
  same_as_catalogue  text,
  same_as_code       text,
  code_conflict      boolean not null default false,
  source_required    text,
  gap_ref            text check (gap_ref ~ '^P11-G[0-9]+$'),
  notes              text,
  primary key (catalogue, legacy_code),
  foreign key (target_dimension, target_value) references config.status_dimension_value (dimension, value),
  foreign key (catalogue, duplicate_of) references config.legacy_status_map (catalogue, legacy_code),
  foreign key (same_as_catalogue, same_as_code) references config.legacy_status_map (catalogue, legacy_code),
  check ((target_dimension is null) = (target_value is null)),
  check ((target_event is null) = (target_event_state is null)),
  check (target_value is not null or target_event is not null or target_object is not null),
  check ((disposition = 'DUPLICATE') = (duplicate_of is not null)),
  check ((same_as_catalogue is null) = (same_as_code is null)),
  check (same_as_catalogue is distinct from catalogue)
);
create index legacy_status_map_target on config.legacy_status_map (target_dimension, target_value);
create index legacy_status_map_duplicate on config.legacy_status_map (catalogue, duplicate_of);
create index legacy_status_map_same_as on config.legacy_status_map (same_as_catalogue, same_as_code);
create index legacy_status_map_module on config.legacy_status_map (target_module);
comment on table config.legacy_status_map is
  'Each legacy status and workflow state mapped to a dimension value, an audit event or a domain object (ADR-029, '
  'ADR-035). Kept for reporting and continuity import; never a status the platform stores.';
comment on column config.legacy_status_map.code_conflict is
  'True when the same code means something else in the other status catalogue; both readings are kept.';

create table config.legacy_form_map (
  catalogue        text not null references config.legacy_catalogue (code),
  sequence_no      int not null check (sequence_no > 0),
  legacy_id        text not null check (legacy_id ~ '^(CRM-F[0-9]{3}|WB-FRM-[0-9]{2}|T[0-9]{1,2}-B[0-9]\.[0-9]-[0-9]{3})$'),
  legacy_name      text not null,
  track            text not null,
  node             text,
  business_intent  text not null,
  target_class     text not null references config.target_class (code),
  target_module    text not null references config.target_module (code),
  merge_target     text not null,
  disposition      text not null check (disposition in ('KEEP', 'MERGE', 'REPLACE', 'RETIRE', 'MIGRATE')),
  data_owner       text not null check (data_owner in ('Compliance (GRC)', 'Investigation team', 'Committee Secretary',
                                                       'Grievance Committee Secretary', 'Owning department / GRC',
                                                       'Case manager / Records', 'Legal', 'Oversight')),
  actor            text not null,
  trigger_text     text,
  status_catalogue text,
  primary_status   text,
  resulting_status text,
  allowed_statuses text[] not null default '{}',
  same_as          text[] not null default '{}',
  legacy_state     text not null check (legacy_state in ('NOT_BUILT', 'LIVE')),
  source_required  text,
  gap_ref          text check (gap_ref ~ '^P11-G[0-9]+$'),
  primary key (catalogue, sequence_no),
  unique (catalogue, legacy_id, legacy_name),
  foreign key (status_catalogue) references config.legacy_catalogue (code),
  foreign key (status_catalogue, primary_status) references config.legacy_status_map (catalogue, legacy_code),
  foreign key (status_catalogue, resulting_status) references config.legacy_status_map (catalogue, legacy_code),
  check ((target_class = 'RETIRED') = (disposition = 'RETIRE')),
  -- DEC-31 as narrowed: the platform has two user-entered forms, the portal report and the grievance submission.
  check (target_class <> 'USER_FORM' or target_module in ('PORTAL_REPORT', 'GRIEVANCE_SUBMISSION')),
  check ((status_catalogue is null) = (primary_status is null and resulting_status is null and cardinality(allowed_statuses) = 0))
);
create index legacy_form_map_class on config.legacy_form_map (target_class);
create index legacy_form_map_module on config.legacy_form_map (target_module);
create index legacy_form_map_status_catalogue on config.legacy_form_map (status_catalogue);
create index legacy_form_map_primary on config.legacy_form_map (status_catalogue, primary_status);
create index legacy_form_map_resulting on config.legacy_form_map (status_catalogue, resulting_status);
comment on table config.legacy_form_map is
  'Each legacy form or control item mapped to one target class and module (ADR-028, ADR-035). A mapping, not a form: '
  'only the WB-FRM rows are LIVE in the forms engine, and they stay enabled. The rationale per row is in '
  'FORM_CATALOGUE_RATIONALIZATION.md.';

-- -----------------------------------------------------------------------------
-- Reason codes the owner's 140-status catalogue names (D S021–S027). OWNER_DEFAULT like the 1870 set they extend.
-- -----------------------------------------------------------------------------
