  ('LEGAL_HOLD_STATUS', 'Legal hold', 'LEGAL_STATE', 'STORED', 'case_mgmt.case_record.legal_hold_status', 'case_mgmt.case_record', 'legal_hold_status', 'A flag separate from the records state.'),
  ('CASE_PRIORITY', 'Case priority', 'FLAG', 'STORED', 'case_mgmt.case_record.priority', 'case_mgmt.case_record', 'priority', null),
  ('CONFLICT_CHECK_STATUS', 'Case conflict check', 'FLAG', 'STORED', 'case_mgmt.conflict_check.status', 'case_mgmt.conflict_check', 'status', 'A declared conflict removes case access (§19).'),
  ('VOTE_RESULT', 'Vote result', 'OUTCOME', 'STORED', 'committee.vote_item.result', 'committee.vote_item', 'result', 'Q57: a tie goes to the chair''s casting vote; all-abstain is NO_DECISION.'),
  ('PACKAGE_STATUS', 'Recommendation package status', 'SUBSTATUS', 'STORED', 'decision.recommendation_package.status', 'decision.recommendation_package', 'status', null),
  ('RECOMMENDATION_ITEM_TYPE', 'Recommendation item type', 'OUTCOME', 'STORED', 'decision.recommendation_item.item_type', 'decision.recommendation_item', 'item_type', null),
