  ('AUTHORITY_DECISION_OUTCOME', 'Authority decision outcome', 'OUTCOME', 'STORED', 'decision.authority_decision.outcome', 'decision.authority_decision', 'outcome', 'Delegation of Authority is SOURCE_REQUIRED.'),
  ('GRIEVANCE_STATUS', 'Grievance status', 'SUBSTATUS', 'STORED', 'grievance.grievance.status', 'grievance.grievance', 'status', null),
  ('CORRECTIVE_ACTION_STATUS', 'Corrective action status', 'EXECUTION_STATE', 'STORED', 'decision.corrective_action.status', 'decision.corrective_action', 'status', 'ADR-033.'),
  ('CASE_STAGE', 'Case stage', 'PRIMARY_STAGE', 'DERIVED', 'derived from the CDF_CASE_V1 state and the open proceedings', null, null, 'Never stored; shown as a derived display status (playbook §9).'),
  ('EXECUTION_STATE', 'Execution state', 'EXECUTION_STATE', 'DERIVED', 'derived from decided items and their corrective actions', null, null, 'Sanction execution has no system of record yet (SOURCE_REQUIRED).'),
  ('GRIEVANCE_FINALITY', 'Grievance finality', 'FLAG', 'DERIVED', 'derived from the decision notice and the grievance window of the rule set in force', null, null, 'Q94: late grievances are flagged, never silently rejected.'),
  ('ESCALATION_STATE', 'Escalation', 'FLAG', 'PLANNED', 'not modelled', null, null, 'Who may escalate, de-escalate or refer to the Board is SOURCE_REQUIRED.'),
  ('QUALITY_REVIEW', 'Quality review', 'SUBSTATUS', 'PLANNED', 'not modelled', null, null, 'Reviewer role is SOURCE_REQUIRED.'),
  ('REPORTER_PROTECTION', 'Reporter protection', 'FLAG', 'PLANNED', 'not modelled', null, null, 'The identity vault exists (0300); a protection flag on the case does not.'),
  ('EXTERNAL_REFERRAL_STATUS', 'External coordination', 'SUBSTATUS', 'PLANNED', 'not modelled', null, null, 'Which bodies and who decides are SOURCE_REQUIRED.');

