  ('CRM_FORM_A_169', 1, 'CRM-F001', 'نموذج إبلاغ عن مخالفة', 'T01 Intake', null, 'اكتمال تقديم البلاغ عبر قناة معتمدة مع تحقق النظام آليًا من الحقول الإلزامية وعدم وجود مدخلات ناقصة أو تالفة.', 'USER_FORM', 'PORTAL_REPORT', 'intake.report (existing)', 'KEEP', 'Compliance (GRC)', 'Reporter', 'تم الاستلام → مسجّل', null, null, null, '{}', '{}', 'NOT_BUILT', null, null),
  ('CRM_FORM_A_169', 2, 'CRM-F002', 'سجل إحالة البلاغ', 'T01 Intake', null, 'توليد رقم مرجعي فريد وربط البلاغ بسجل الامتثال المركزي واعتماد ملكية المعالجة رسميًا.', 'GENERATED_RECORD', 'CASE_INTAKE_SOURCE', 'case_source', 'MERGE', 'Compliance (GRC)', 'System', 'مسجّل → مُحال إلى إدارة الحوكمة والامتثال المؤسسي', null, null, null, '{}', '{}', 'NOT_BUILT', null, null),
  ('CRM_FORM_A_169', 3, 'CRM-F003', 'نموذج التقييم المبدئي', 'T02 Preliminary review', null, 'قبول البلاغ رسميًا من مختص الامتثال بعد التحقق من اكتمال الشكل وتوافر الحد الأدنى من المعلومات.', 'GUIDED_TASK', 'PRELIM_ASSESSMENT', 'preliminary assessment task', 'KEEP', 'Compliance (GRC)', 'Assigned investigator', 'مُحال إلى إدارة الحوكمة والامتثال المؤسسي → التقييم المبدئي', null, null, null, '{}', '{}', 'NOT_BUILT', null, null),
  ('CRM_FORM_A_169', 4, 'CRM-F004', 'نموذج تصنيف بلاغ غير جدي', 'T02 Preliminary review', null, 'ثبوت عدم جدية البلاغ أو وجود مؤشرات كيدية أو إساءة استخدام دون وقائع قابلة للتحقق.', 'WORKFLOW_DECISION', 'PRELIM_CLOSE_OUTCOME', 'preliminary_recommendation(outcome code)', 'MERGE', 'Compliance (GRC)', 'Preparer → Director → Sector head', 'التقييم المبدئي → غير جدي', null, null, null, '{}', '{}', 'NOT_BUILT', null, 'P11-G1'),
  ('CRM_FORM_A_169', 5, 'CRM-F005', 'نموذج تصنيف خارج النطاق', 'T02 Preliminary review', null, 'التحقق من أن موضوع البلاغ لا يدخل ضمن اختصاص الصندوق النظامي أو مهامه التنظيمية.', 'WORKFLOW_DECISION', 'PRELIM_CLOSE_OUTCOME', 'preliminary_recommendation(outcome code)', 'MERGE', 'Compliance (GRC)', 'Preparer → Director → Sector head', 'التقييم المبدئي → خارج النطاق', null, null, null, '{}', '{}', 'NOT_BUILT', null, null),
