-- -----------------------------------------------------------------------------
-- RLS (SELECT only; no write grants for application roles)
-- -----------------------------------------------------------------------------
alter table config.target_class enable row level security;
alter table config.target_module enable row level security;
alter table config.legacy_catalogue enable row level security;
alter table config.status_dimension enable row level security;
alter table config.status_dimension_value enable row level security;
alter table config.legacy_status_map enable row level security;
alter table config.legacy_form_map enable row level security;

create policy target_class_read on config.target_class for select to authenticated
  using (authz.current_user_id() is not null);
create policy target_module_read on config.target_module for select to authenticated
  using (authz.current_user_id() is not null);
create policy legacy_catalogue_read on config.legacy_catalogue for select to authenticated
  using (authz.current_user_id() is not null);
create policy status_dimension_read on config.status_dimension for select to authenticated
  using (authz.current_user_id() is not null);
create policy status_dimension_value_read on config.status_dimension_value for select to authenticated
  using (authz.current_user_id() is not null);
create policy legacy_status_map_read on config.legacy_status_map for select to authenticated
  using (authz.current_user_id() is not null);
create policy legacy_form_map_read on config.legacy_form_map for select to authenticated
  using (authz.current_user_id() is not null);

grant select on config.target_class, config.target_module, config.legacy_catalogue, config.status_dimension,
  config.status_dimension_value, config.legacy_status_map, config.legacy_form_map to authenticated;
